#include "opensim/scene/world.hpp"
#include <bit>
#include <cmath>
#include <iostream>
#include <limits>
#include <set>
#include <sstream>
#include <stdexcept>
#include <thread>
using namespace opensim;
namespace {
int checks=0;
void check(bool okay,const char* name){if(!okay)throw std::runtime_error(name);++checks;}
template<class F>bool throws(F call){try{call();return false;}catch(const std::exception&){return true;}}
std::uint32_t bits(float value){return std::bit_cast<std::uint32_t>(value);}
float parse_bits(const std::string& text){return std::bit_cast<float>(static_cast<std::uint32_t>(std::stoul(text,nullptr,16)));}
void terrain_probe(){scene::Terrain terrain(32,32);for(int x=0;x<32;++x)for(int y=0;y<32;++y)terrain.set(x,y,static_cast<float>((x*17-y*11)%37)*.25f);terrain.clear_taint();std::string line;while(std::getline(std::cin,line)){std::istringstream in(line);char op;in>>op;try{if(op=='h'){std::string x,y;in>>x>>y;std::cout<<std::hex<<bits(terrain.height_at(parse_bits(x),parse_bits(y)))<<std::dec;}else if(op=='p'){int x,y;std::string sub,mul;in>>x>>y>>sub>>mul;auto values=terrain.patch(x,y,parse_bits(sub),parse_bits(mul));for(auto value:values)std::cout<<std::hex<<bits(value)<<',';std::cout<<std::dec;}else if(op=='m'){int x,y;in>>x>>y;auto [min,max]=terrain.patch_min_max(x,y);std::cout<<std::hex<<bits(min)<<','<<bits(max)<<std::dec;}else if(op=='s'){int x,y;std::string value;in>>x>>y>>value;terrain.set(x,y,parse_bits(value));std::cout<<terrain.tainted_count();}else if(op=='t'){int x,y,clear;in>>x>>y>>clear;std::cout<<terrain.tainted_patch(x,y,clear)<<','<<terrain.tainted_count();}else if(op=='n'){int start;in>>start;std::cout<<terrain.next_taint(start)<<','<<terrain.tainted_count();}else if(op=='c'){terrain.clear_taint();std::cout<<terrain.tainted_count();}else if(op=='a'){terrain.taint_all();std::cout<<terrain.tainted_count();}else throw std::runtime_error("op");}catch(...){std::cout<<"EX";}std::cout<<'\n';}}
void terrain_tests(){
 scene::Terrain t(32,16);check(t.width()==32&&t.height()==16&&t.get(0,0)==0&&!t.tainted(),"source dimension constructor initializes zero without taints");
 t.set(16,0,5);check(t.tainted_count()==1&&t.tainted_patch(1,0),"changed height taints correct16m patch");t.set(16,0,5);check(t.tainted_count()==1,"same value does not add taint");check(t.next_taint()==1&&!t.tainted(),"inclusive taint drain clears patch");
 t.clear_land();check(t.get(31,15)==21&&!t.tainted(),"ClearLand defaults21 and does not taint");t.set(0,0,-0.f);t.clear_taint();t.set(0,0,0.f);check(std::signbit(t.get(0,0))&&!t.tainted(),"equal signed zero preserves stored bit pattern");
 t.clear_land(0);t.set(1,0,10);t.set(0,1,20);t.set(1,1,100);check(t.height_at(.25f,.75f)==35.f&&t.height_at(.75f,.25f)==30.f,"height sampling follows source triangles");check(t.height_at(-1,.25f)==5.f&&t.height_at(.25f,-1)==2.5f,"height sampling interpolates clamped edges");check(t.height_at(100,100)==0.f,"height sampling clamps finite outer edge");check(throws([&]{t.height_at(std::numeric_limits<float>::quiet_NaN(),0);}),"NaN coordinate preserves source indexing failure");
 for(int x=0;x<32;++x)for(int y=0;y<16;++y)t.set(x,y,float(x*100+y));auto patch=t.patch(1,0);auto floats=t.serialized_floats();auto compressed=t.compressed_map();check(patch[3*16+2]==1803&&floats[3*32+18]==1803&&compressed[18*16+3]==1803,"viewer patches and serialization retain distinct source orderings");
 t.clear_land(0);t.set(0,15,-100);t.set(1,15,100);auto mm=t.patch_min_max(0,0);check(mm.first==0&&mm.second==100&&t.patch(0,0)[15*16]==-100,"patch minmax retains source first-column omission");t.clear_taint();t.taint_all();auto clone=t.clone();check(clone.get(0,15)==-100&&!clone.tainted()&&t.tainted_count()==2,"source Clone copies heights without taints");check(throws([&]{t.get(-1,0);})&&throws([&]{t.patch(2,0);}),"checked native array/patch bounds");
 auto nan=std::numeric_limits<float>::quiet_NaN();t.set(0,0,nan);t.clear_taint();t.set(0,0,nan);check(t.tainted(),"NaN assignment always marks source change");
}
void world_tests(){
 framework::Uuid owner("00000000-0000-0000-0000-000000000007");scene::World world({},256,256,100);auto object=scene::SceneObject::primitive(owner,{128,128,25});check(!object.id.is_zero()&&object.owner==owner&&object.creator==owner&&object.rezzer==owner&&object.last_owner==owner,"new primitive source identity/ownership");check(object.name=="Object"&&object.rotation.w==1&&!object.texture_entry.empty()&&object.shape.pcode==9&&object.shape.path_scale_x==100,"primitive source name, identity rotation, texture and box shape");auto added=world.add(object);check(added&&added->local_id==101&&added->changed&&added->attached_to_backup,"add assigns shared local ID and backup state");check(world.allocate_local_id()==102,"avatar shares same allocator");check(!world.add(object)&&world.size()==1,"duplicate UUID rejected before ID allocation");check(!world.add(scene::SceneObject{}),"zero UUID rejected");
 check(world.update_transform(object.id,{1,2,3},{0,0,0,1},{2,3,4})&&world.object(101)->position==framework::Vector3{1,2,3},"transform changes visible through local index");check(world.update_motion(object.id,{4,5,6},{1,2,3},{2,2,2}),"motion state updates");check(world.remove(object.id)&&!world.object(101)&&!world.remove(object.id),"remove clears both indexes and missing remove returns false");auto events=world.drain_events();check(events.size()==4&&events[0].kind==scene::WorldEventKind::Added&&events[1].kind==scene::WorldEventKind::Updated&&events[3].kind==scene::WorldEventKind::Removed&&events[0].object.position.x==128&&events[3].sequence==4,"lifecycle events retain snapshots and order");check(world.drain_events().empty(),"events drain once");
 auto first=scene::SceneObject::primitive(owner,{0,0,0});first.local_id=42;auto second=scene::SceneObject::primitive(owner,{0,0,0});second.local_id=42;world.add(first,false,false);world.add(second,false,false);check(world.size()==2&&world.object(42)->id==second.id,"source explicit local-ID collision overwrites local lookup");world.remove(first.id);check(!world.object(42)&&world.object(second.id).has_value(),"source removal unconditionally clears collided local index");
 auto attachment=scene::SceneObject::primitive(owner,{0,0,0});attachment.is_attachment=true;attachment.shape.state=1;attachment.parent_id=9;auto a=world.add(attachment,true);check(a&&a->parent_id==9&&!a->attached_to_backup&&a->changed,"attachment root parent and backup state");scene::World wrapping({},16,16,0xffffffffu);check(wrapping.allocate_local_id()==0&&wrapping.allocate_local_id()==1,"unchecked uint32 local-ID wrap includes zero");
 scene::World event_world;auto event_object=scene::SceneObject::primitive(owner,{0,0,0});event_object.flags=8;event_world.add(event_object,false,false);event_world.set_inventory_state(event_object.id,false,true,true,0x10280u);check(event_world.object(event_object.id)->flags==0x102c8u,"source local touch/money/drop flags preserve unrelated flags and scripted state");event_world.set_inventory_state(event_object.id,true,false,false,0u);check(event_world.object(event_object.id)->flags==8&&event_world.object(event_object.id)->inventory_empty,"clearing script registrations clears only source local flags");
 scene::World threaded;std::mutex ids_mutex;std::set<std::uint32_t> ids;std::vector<std::thread> threads;for(int k=0;k<8;++k)threads.emplace_back([&]{for(int i=0;i<1000;++i){auto id=threaded.allocate_local_id();std::lock_guard lock(ids_mutex);ids.insert(id);}});for(auto& thread:threads)thread.join();check(ids.size()==8000&&*ids.begin()==720001&&*ids.rbegin()==728000,"concurrent shared allocator produces unique source increment sequence");
}
}
int main(int argc,char** argv){try{if(argc>1&&std::string(argv[1])=="--terrain-probe"){terrain_probe();return 0;}terrain_tests();world_tests();std::cout<<"PASS: "<<checks<<" scene/world foundation checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
